:::: {.g-col-4}

```{ojs}
//| panel: input
//| echo: false

viewof K = Inputs.range(
  [1, 30], 
  {value: 10, step: 1, label: tex`K`}
)

viewof Delta = Inputs.range(
  [0, 20], 
  {value: 4, step: 0.1, label: tex`\Delta`}
)

tex`\pi = ${pi}`
```

::::

:::: {.g-col-8 .center}

```{ojs}
math = require("mathjs")
binomial = require( 'https://cdn.jsdelivr.net/gh/stdlib-js/stats-base-dists-binomial@umd/browser.js' )

pi = (1 + math.sqrt(1 - math.exp(-2 * Delta / K))) / 2

pts = K + 1

dat = Array(pts).fill().map((element, index) => {
  let x = index;
  let p = binomial.pmf(index, K, 0.5);
  let q = binomial.pmf(index, K, pi);
  return ({
    x: x,
    p: p,
    q: q
  })
})

```

```{ojs}
//| echo: false
//| label: fig-McCulloch
//| fig-cap: "Predicted Binomial$(K,\\pi)$ distribution (in black) that diverges by $\\Delta$ from Binomial$(K,\\frac{1}{2})$"


Plot.plot({
  height: 350,
  width: 700,
  y: {
    grid: false,
    label: "Probability"
  },
  x: {
    label: "X"
  },   
  marks: [
    Plot.barY(dat, {x: "x", y: "p", fill: "blue", fillOpacity: 0.2}),
    Plot.ruleX(dat, {x: "x", y: "q", strokeWidth: 4}),
    Plot.dot(dat, {x: "x", y: "q", fill: "black"})
  ]
})
```


